import styled from "styled-components";

export const Wrapper = styled.div`
    background-color: #fff;
    border-radius: 4px;
    margin: 0 auto;
    padding-bottom: 180px;
    transition: all 0.3s ease;
`

export const FileLink = styled.a`
  cursor:pointer;
  color:blue;
  text-decoration:underline;
`;
